 await check('invalid numeric and state combinations reject without coercion',()=>{for(const v of [false,-1,NaN,Infinity,1e6+1]){const s=sample();s.entities[0].fields.depth=v;assert.throws(()=>world.validate(s,s.sessionId));}for(const patch of [s=>s.entities[3].fields.state=1,s=>s.entities[3].fields.fill=.5,s=>s.entities[11].fields.dive=0,s=>s.entities[14].fields.resourceCount++,s=>s.entities[6].fields.multiplicator=2,s=>s.entities[6].fields.resources.pop()]){const s=sample();patch(s);assert.throws(()=>world.validate(s,s.sessionId));}});
 await check('world size ids and coordinate uniqueness reject before build',()=>{for(const patch of [s=>s.entities=Array.from({length:257},(_,i)=>({...s.entities[0],netId:i+1})),s=>s.entities[0].netId=257,s=>s.entities[1].netId=1,s=>s.entities[1].position=s.entities[0].position,s=>s.entities[0].position=[65,0],s=>s.entities[0].position=[.5,0]]){const s=sample();patch(s);assert.throws(()=>world.validate(s,s.sessionId));}});
 await check('context format epoch revision and invalid UTF8 are rejected',()=>{for(const patch of [{format:'p2p-snapshot13-experiment-v1'},{epoch:2},{revision:2},{sceneId:'old'},{sessionId:'desktop13-snapshot-999'}])assert.throws(()=>world.validate({...sample(),...patch},sample().sessionId));assert.throws(()=>world.decode(Buffer.from([0xc0,0xaf]),sample().sessionId),/INVALID_UTF8/);});
 await check('byte boundary 65536 accepts valid padded JSON while 65537 refuses',()=>{const b=world.encode(sample(),sample().sessionId),max=Buffer.concat([b,Buffer.alloc(65536-b.length,32)]);assert.equal(codec.frameBytes(max,sample().sessionId).chunks,8);assert.throws(()=>world.decode(Buffer.concat([max,Buffer.from(' ')]),sample().sessionId),/SNAPSHOT_SIZE/);});
 await check('real 256 entity frame order checksum and incomplete data never apply',()=>{const s=world.sample(undefined,256),batch=codec.frames(s,s.sessionId);for(const kind of ['missing','order','checksum']){let applied=0;const r=new codec.Receiver(s.sessionId,()=>applied++);r.accept(batch.frames[0]);if(kind==='missing')assert.throws(()=>r.accept(batch.frames.at(-1)),/MISSING/);else{const parts=batch.frames.slice(1,-1).map(Buffer.from);if(kind==='order')parts[0].writeUInt32BE(1,4);else parts[0][20]^=1;assert.throws(()=>{parts.forEach(p=>r.accept(p));r.accept(batch.frames.at(-1));},/CHUNK|CHECKSUM/);}assert.equal(applied,0);assert.equal(r.state().pendingBytes,0);}});
 await check('complete 256 entity receiver applies once with same receipt and bounded metrics',()=>{const s=world.sample(undefined,256),batch=codec.frames(s,s.sessionId);let applied=0;const r=new codec.Receiver(s.sessionId,v=>{assert.equal(v.entities.length,256);applied++;});batch.frames.forEach(f=>r.accept(f));assert.equal(applied,1);assert.equal(r.receipt.bytes,batch.bytes);assert.equal(r.receipt.sha256,batch.sha256);assert.equal(r.state().metrics.chunks,batch.chunks);assert.ok(r.state().metrics.decodeMs>=0);assert.throws(()=>r.accept(batch.frames[0]),/ALREADY_APPLIED/);assert.equal(applied,1);});
