 await check('command request schema rejects extra missing coerced overflowing or unsupported operations',()=>{const m=commandModel(),r=m.request();assert.deepEqual(command.request(r),r);for(const patch of [{price:1},{requestId:0},{requestId:65},{requestId:true},{requestId:1.1},{epoch:2},{name:'pump2'},{name:'cube'},{baseRevision:0},{baseStateHash:'x'},{position:[65,0]},{position:[0.5,0]},{position:[NaN,0]},{position:[0,0,0]}])assert.throws(()=>command.request({...r,...patch}));const missing={...r};delete missing.position;assert.throws(()=>command.request(missing));});
 await check('host costs 2048 4096 8192 exactly and fourth rejection leaves revision ID resources and stats unchanged',()=>{const m=commandModel();for(let i=0;i<3;i++){const result=m.machine.receive(m.peers[i],m.request());assert.equal(result.kind,'committed');assert.equal(result.value.entity.netId,25+i);assert.equal(result.value.commandId,i+1);assert.equal(result.value.revision,i+2);assert.equal(result.value.price[2],[2048,4096,8192][i]);assert.equal(result.value.resourcesAfter[2],[14336,10240,2048][i]);assert.equal(result.value.machinesBuildAfter,i+1);m.ack(result.value);}const before=m.value,r=m.machine.receive(m.peers[0],m.request(2));assert.equal(r.value.reason,'INSUFFICIENT_RESOURCES');assert.deepEqual(m.value,before);assert.equal(m.creates,3);});
