 await check('reused ID with changed content cannot replace the original immutable verdict',()=>{const m=commandModel(),r=m.request(),a=m.machine.receive(m.peers[0],r);assert.equal(m.machine.receive(m.peers[0],{...r,position:[10,5]}).value.reason,'REQUEST_ID_REUSE');assert.deepEqual(m.machine.receive(m.peers[0],r).value,a.value);assert.equal(m.creates,1);});
 await check('three actual peer receipts are needed and duplicates do not release pending command',()=>{const m=commandModel(),a=m.machine.receive(m.peers[0],m.request()).value,ack=command.receipt(a);assert.equal(m.machine.acknowledge(m.peers[0],ack),false);assert.equal(m.machine.acknowledge(m.peers[0],ack),false);assert.equal(m.machine.state().pending.ackedCount,1);assert.throws(()=>m.machine.acknowledge('guest-88',ack));assert.throws(()=>m.machine.acknowledge(m.peers[1],{...ack,stateHash:'0'.repeat(64)}));assert.throws(()=>m.machine.acknowledge(m.peers[1],{...ack,extra:1}));assert.equal(m.machine.acknowledge(m.peers[1],ack),false);assert.ok(m.machine.pending);assert.equal(m.machine.acknowledge(m.peers[2],ack),true);assert.equal(m.machine.pending,null);});
 await check('concurrent other guest requests are BUSY and retry needs new ID and current state',()=>{const m=commandModel(),r=m.request(),a=m.machine.receive(m.peers[0],r);for(const p of m.peers.slice(1))assert.equal(m.machine.receive(p,r).value.reason,'BUSY');m.ack(a.value);assert.equal(m.machine.receive(m.peers[1],r).value.reason,'BUSY');assert.equal(m.machine.receive(m.peers[1],{...r,requestId:2}).value.reason,'STALE_REVISION');const b=m.machine.receive(m.peers[1],m.request(3));assert.equal(b.kind,'committed');assert.equal(m.creates,2);});
 await check('not ready and bad base digest reject with no native mutation and cached rejection stays stable',()=>{const m=commandModel(),r=m.request();m.enable(false);assert.equal(m.machine.receive(m.peers[0],r).value.reason,'NOT_READY');m.enable(true);assert.equal(m.machine.receive(m.peers[0],r).value.reason,'NOT_READY');assert.equal(m.machine.receive(m.peers[0],{...m.request(2),baseStateHash:'0'.repeat(64)}).value.reason,'STATE_MISMATCH');assert.equal(m.creates,0);assert.equal(m.value.revision,1);});
 await check('request ID budget bounds all ledgers at 64 per authenticated guest without evicting old verdicts',()=>{const m=commandModel();m.enable(false);for(const p of m.peers)for(let i=1;i<=64;i++)m.machine.receive(p,m.request(i));assert.equal(m.machine.state().ledgerSize,192);for(const p of m.peers)assert.throws(()=>m.machine.receive(p,m.request(65)));assert.equal(m.machine.state().ledgerSize,192);assert.equal(m.machine.receive(m.peers[0],m.request()).replay,true);});
 await check('guest applies once and only reACKs a matching historical commit after newer state',()=>{const m=commandModel(),before=m.state(),a=m.machine.receive(m.peers[0],m.request()).value,g=new command.GuestLedger();let applied=0;const ack=g.receive(a,before,()=>{applied++;return {revision:a.revision,stateHash:a.afterHash};});assert.deepEqual(ack,command.receipt(a));assert.deepEqual(g.receive(a,{revision:4,stateHash:'0'.repeat(64)},()=>{throw Error('MUST_NOT_APPLY');}),ack);assert.equal(applied,1);assert.equal(g.state().duplicateCommits,1);const corrupt=command.seal({...a,afterHash:'f'.repeat(64)});assert.throws(()=>g.receive(corrupt,before,()=>{}),/REPLAY_MISMATCH/);});
 await check('bad or out of order Host commits are rejected before any guest native apply',()=>{const m=commandModel(),before=m.state(),a=m.machine.receive(m.peers[0],m.request()).value;for(const value of [{...a,commitHash:'0'.repeat(64)},command.seal({...a,beforeHash:'f'.repeat(64)}),command.seal({...a,commandId:2,prevRevision:2,revision:3,machinesBuildAfter:2})]){const g=new command.GuestLedger();let applied=0;assert.throws(()=>g.receive(value,before,()=>applied++));assert.equal(applied,0);}for(const patch of [{entity:{...a.entity,netId:257}},{price:[0,0,-1]},{machinesBuildAfter:4},{entity:{...a.entity,fields:{soul:1,depth:1,spoolup:0}}}])assert.throws(()=>command.seal({...a,...patch}));});
 await check('guest after-state mismatch cannot create a successful applied ledger or receipt',()=>{const m=commandModel(),before=m.state(),a=m.machine.receive(m.peers[0],m.request()).value,g=new command.GuestLedger();assert.throws(()=>g.receive(a,before,()=>({revision:a.revision,stateHash:'0'.repeat(64)})),/RESULT_STATE/);assert.equal(g.applied.size,0);});
