 await check('new control wire rejects messages above 4 KiB before routing without mutating a peer',async()=>{const p=pair();try{await ready(p);assert.throws(()=>p.host.forPeer(p.peerIds[0]).sendCommand('commit',{blob:'x'.repeat(4096)}),/ROOM_CONTROL_SIZE/);p.left[0].onmessage({data:' '.repeat(4097)});assert.ok(p.host.state().peers[p.peerIds[0]].rejectionCodes.includes('ROOM_CONTROL_SIZE'));assert.equal(p.applied[0].length,0);}finally{p.close();}});
 await check('raw and already normalized state reports preserve evidence under repeated conversion',()=>{for(const error of [null,'diagnostic-present']){const raw={instance:'guest1',p2p:{signaling:{status:'signaling-ready',socketOpen:true,iceServers:[],error},transport:{peers:[]}}};const once=controller.cleanStatus(raw),twice=controller.cleanStatus(once);assert.deepEqual(twice,once);assert.equal(twice.p2p.signaling.iceServerCount,0);assert.equal(twice.p2p.signaling.errorPresent,!!error);}});
