const byId=(ctx,id)=>ctx.clients.find(c=>c.instance===id);
const evaluate=(ctx,id,code)=>byId(ctx,id).call('evaluate',code);
async function initial(ctx){await sendAndConfirm(ctx,1);return ctx.wait(s=>IDS.every(id=>s[id].wire.commands.ready&&s[id].world.commandReady),10000);}
function assertConverged(ctx,states,builds=0){
 controller.assertGroup(states,ctx.attempt,'automated',ctx.runId);
 const value=world.sample('desktop13-snapshot-'+ctx.attempt,ctx.sceneSize),before=value.entities.slice();
 value.revision=builds+1;value.machinesBuild=builds;
 for(let i=0;i<builds;i++){value.entities.push({netId:ctx.sceneSize+i+1,name:'pump',position:[...command.TARGETS[i]],fields:{soul:1,depth:0,spoolup:0}});value.resources[2]-=256*2**(ctx.sceneSize/8+i);}
 const sha=world.digest(world.encode(value,value.sessionId));
 for(const id of IDS){const v=states[id].world;assert.equal(v.entities,ctx.sceneSize+builds,id+' entity count');assert.equal(v.revision,builds+1);assert.equal(v.machinesBuild,builds);assert.equal(v.initialIdentityPreserved,true);assert.equal(v.commandMetrics.nativeCreates,builds);assert.equal(v.commandMetrics.applies,builds);assert.equal(v.nativeTypes,true);assert.equal(v.sha256,sha,id+' canonical world');assert.deepEqual(v.entityRows.filter(e=>e.netId<=ctx.sceneSize),world.validate({...value,entities:before},value.sessionId).entities);assert.equal(v.graphSha256,states.host.world.graphSha256);assert.equal(v.commandStateHash,states.host.world.commandStateHash);assert.equal(v.worldDigest,states.host.world.worldDigest);assert.deepEqual(v.resources,value.resources);assert.equal(v.typeCount,ctx.sceneSize?8:0);assert.equal(states[id].wire.captureCount,id==='host'?1:0);if(id!=='host')assert.equal(states[id].wire.commands.guest.applied.length,builds);}
 const host=states.host.wire.commands.host;assert.equal(host.history.length,builds);assert.equal(host.pending,null);
 for(const [i,row]of host.history.entries()){assert.equal(row.commit.commandId,i+1);assert.equal(row.commit.entity.netId,ctx.sceneSize+i+1);assert.equal(row.hostCommitted,true);assert.equal(row.allAcknowledged,true);assert.equal(row.ackedCount,3);assert.deepEqual(Object.keys(row.acknowledgments).sort(),IDS.slice(1).map(id=>ctx.mapping[id]).sort());for(const ack of Object.values(row.acknowledgments))assert.equal(ack.stateHash,row.commit.afterHash);}
 return states;
}
async function clickBuild(ctx,id){return evaluate(ctx,id,`(()=>{const b=document.getElementById('build-command-request');if(!b||b.disabled)throw Error('BUILD_BUTTON_NOT_READY');b.click();return Snapshot13.wire.state().commands.events.filter(e=>e.type==='guest-requested').at(-1).request;})()`);}
async function buildOne(ctx,id,number){const request=await clickBuild(ctx,id);const states=await ctx.wait(s=>s.host.wire.commands.host?.history[number-1]?.allAcknowledged&&IDS.every(k=>s[k].wire.commands.ready),10000);assertConverged(ctx,states,number);return {states,request};}
function rawRequest(states,requestId=40,patch={}){return {requestId,epoch:1,baseRevision:states.host.world.revision,baseStateHash:states.host.world.commandStateHash,name:'pump',position:[...command.TARGETS[Math.min(states.host.world.machinesBuild,3)]],...patch};}
async function injectRequest(ctx,id,value,patch={}){return evaluate(ctx,id,'Snapshot13.wire.testRequest('+JSON.stringify(value)+','+JSON.stringify(patch)+')');}
async function waitVerdict(ctx,id,requestId,reason){return ctx.wait(s=>s.host.wire.commands.events.some(e=>e.type==='request-rejected'&&e.peerId===ctx.mapping[id]&&e.requestId===requestId&&e.reason===reason),10000);}
